~()?\"']/g, ' ')\n .replace(/\\s+/g,:
~()?"]/জি, '')
    .replace(/\s+/g, ' ')
    .ট্রিম();
}

/**
 * উচ্চ-নির্ভুল অনুসন্ধান এবং শব্দার্থক ক্যোয়ারী ইঞ্জিন
 */
এক্সপোর্ট অ্যাসিঙ্ক ফাংশন অনুসন্ধান বাক্য(
  প্রশ্ন: স্ট্রিং,
  ফিল্টার: SearchFilterOptions = {}
): প্রতিশ্রুতি <{ ফলাফল: SentenceItem[]; মোট: সংখ্যা; শব্দার্থক মিল?: শব্দার্থ ব্যাখ্যামূলক ম্যাচ[] }> {
  const all = await loadSentences();
  const normalizedQuery = normalizeText(query);
  const queryTokens = normalizedQuery? normalizedQuery.split('').ফিল্টার(বুলিয়ান): [];

  const {
    cefr = 'সব',
    বিভাগ = 'সমস্ত',
    বিভাগ = 'সমস্ত',
    উপশ্রেণি = 'সমস্ত',
    ব্যাকরণ = 'সমস্ত',
    আনুষ্ঠানিকতা = 'সব',
    সীমা = ৫০,
    অফসেট = 0,
  } = ফিল্টার;

  // ফিল্টার পাস
  filtered = all.filter(s => {
    যদি (cefr !== 'all' && s.cefr !== cefr) মিথ্যা ফেরত দেয়;
    যদি (বিভাগ !== 'all' && s.section !==section) ফেরত মিথ্যা;
    যদি (বিভাগ!== 'all' &&s.category !== শ্রেণী) মিথ্যা ফেরত দেয়;
    যদি (উপশ্রেণি !== 'সমস্ত' && s.subcategory !== উপশ্রেণি) মিথ্যা ফেরত দেয়;
    যদি (grammar !== 'all' && !s.grammar.toLowerCase().includes(grammar.toLowerCase())) মিথ্যা ফেরত দেয়;
    যদি (আনুষ্ঠানিকতা !== 'all' && s.formality.toLowerCase() !== formality.toLowerCase()) মিথ্যা ফেরত দেয়;
    সত্য ফিরে
  });

  যদি (!normalizedQuery) {
    const total = filtered.length;
    const paginated = ফিল্টার করা। স্লাইস (অফসেট, অফসেট + সীমা);
    প্রত্যাবর্তন { ফলাফল: পৃষ্ঠাযুক্ত, মোট };
  }

  // স্কোরিং অ্যালগরিদম
  ইন্টারফেসস্কোরডআইটেম {
    আইটেম:বাক্য আইটেম;
    স্কোর: সংখ্যা;
    দৃষ্টিভঙ্গি: শব্দার্থ ব্যাখ্যামূলক ম্যাচ ['matchedAspect'];
  }

  const স্কোর: ScoredItem[] = [];

  জন্য (ফিল্টার করা কনস্ট) {
    যাক স্কোর = ০;
    let matchedAspect: SemanticExplanationMatch['matchedAspect'] = 'ইংরেজি';

    const normEn = normalizeText(s.english);
    const normEg = normalizeText(s.arabicEg);
    const normFusha = normalizeText(s.arabicFusha);
    const normGrammar = normalizeText(s.grammar);
    const normPurpose = normalizeText(s.purpose);

    // সঠিক পূর্ণ বাক্যের মিল
    যদি (normEn === normalizedQuery) {
      স্কোর += 100;
      matchedAspect = 'ইংরেজি';
    } অন্যথায় যদি (normEg === normalizedQuery) {
      স্কোর += 95;
      matchedAspect = 'আরবি-যেমন';
    } অন্যথায় যদি (normFusha === normalizedQuery) {
      স্কোর += 90;
      matchedAspect = 'আরবি-ফুশা';
    }

    //সাবস্ট্রিং ধারণ করে
    যদি (normEn.includes(normalizedQuery)) {
      স্কোর += 50;
      matchedAspect = 'ইংরেজি';
    } অন্য যদি (normEg.includes(normalizedQuery)) {
      স্কোর += 45;
      matchedAspect = 'আরবি-যেমন';
    } অন্য যদি (normFusha.includes(normalizedQuery)) {
      স্কোর += 40;
      matchedAspect = 'আরবি-ফুশা';
    } অন্য যদি (normGrammar.includes(normalizedQuery)) {
      স্কোর += 35;
      matchedAspect = 'ব্যাকরণ';
    } অন্য যদি (normPurpose.includes(normalizedQuery)) {
      স্কোর += 30;
      matchedAspect = 'ধারণা';
    }

    // টোকেন ম্যাচ
    যাক টোকেন ম্যাচ = 0;
    (queryTokens এর const টোকেন) {
      if (normEn.includes(token)) tokenMatches += 5;
      if (normEg.includes(token)) tokenMatches += 4;
      if (normFusha.includes(token)) tokenMatches += 3;
      যদি (s.vocabulary.some(v => normalizeText(v).includes(token))) tokenMatches += 4;
      যদি (s.tags.some(t => normalizeText(t).includes(token))) tokenMatches += 3;
    }
    স্কোর += টোকেন ম্যাচ;

    যদি (স্কোর > 0) {
      scored.push({ আইটেম: s, স্কোর, দিক: matchedAspect });
    }
  }

  scored.sort((a, b) => b.score - a.score);

  // শীর্ষস্থানীয় আইটেমগুলির জন্য শব্দার্থিক ব্যাখ্যা মেলে
  const semanticMatches: SemanticExplanationMatch[] = scored.slice(0, 5).map(s => {
    let nuance = '';
    যদি (s.item.grammar.toLowerCase().includes('অতীত ক্রমাগত')) {
      nuance = 'অতীত অবিচ্ছিন্ন কাল দেখায় যে একটি ঘটনা অতীতে একটি নির্দিষ্ট সময়ে চলমান ছিল।';
    } অন্যথায় যদি (s.item.grammar.toLowerCase().includes('present perfect continuous')) {
      nuance = 'বর্তমান নিখুঁত অবিচ্ছিন্ন কাল অতীতের সময়ের উপর জোর দেয় এবং কথা বলার মুহূর্ত পর্যন্ত চলতে থাকে।';
    } অন্যথায় যদি (s.item.grammar.toLowerCase().includes('future perfect')) {
      nuance = 'ভবিষ্যৎ নিখুঁত কাল ব্যক্ত করে যে একটি ঘটনা ভবিষ্যতে একটি নির্দিষ্ট সময়ের আগে সম্পন্ন হবে।';
    } অন্যথায় যদি (s.item.grammar.toLowerCase().includes('indirect')) {
      nuance = 'পরোক্ষ অনুরোধের ফর্ম ইংরেজি যোগাযোগে কূটনৈতিক শিষ্টাচারের শীর্ষস্থান।';
    }
    ফিরে
      বাক্য: s.item,
      মিলের স্কোর: Math.min(100, s.score),
      nuanceExplanationAr: nuance,
      matchedAspect: s.aspect,
    };
  });

  const total = স্কোর করা। দৈর্ঘ্য;
  const paginated = scored.slice(offset, offset + limit).map(s => s.item);

  ফিরে
    ফলাফল: পৃষ্ঠাযুক্ত,
    মোট,
    শব্দার্থিক মিল,
  };
}

