এক্সপোর্ট অ্যাসিঙ্ক ফাংশন getSentenceOfTheWeek(): প্রতিশ্রুতি<SentenceItem | শূন্য> {
  const all = await loadSentences();
  যদি (সমস্ত। দৈর্ঘ্য === 0) রিটার্ন নাল;

  const today = নতুন তারিখ();
  const weekNumber = Math.ceil(
    ((today.getTime() - নতুন তারিখ(today.getFullYear(), 0, 1)। getTime()) / 86400000 + 1) / 7
  );
