  const পুল = b2c1.দৈর্ঘ্য > 0? b2c1:সমস্ত;
  const index = Math.abs((weekNumber * 31) % pool.length);
  রিটার্ন পুল [সূচক] || পুল [0];
}

/**
 * এলোমেলো বাক্য, ঐচ্ছিক CEFR বা বিভাগ ফিল্টার পান
 */
এক্সপোর্ট অ্যাসিঙ্ক ফাংশন getRandomSentence(cefr?: CEFRLevel, section?: string): প্রতিশ্রুতি<SentenceItem | শূন্য> {
  const all = await loadSentences();
  let pool = all;
  যদি (cefr) {
    পুল = পুল ফিল্টার (s => s.cefr === cefr);
  }
  যদি (বিভাগ) {
    পুল = পুল। ফিল্টার (s => s. বিভাগ === বিভাগ);
  }
  if (পুল। দৈর্ঘ্য === 0) রিটার্ন নাল;
  const randIdx = Math.floor(Math.random() * pool.length);
  রিটার্ন পুল [randIdx];
}
